class VisualQAPipeline:
    def __init__(self, model_name: str):
        self.model_name = model_name
        self.history = []

    def _mock_answer(self, question: str) -> str:
        q = question.lower()
        if 'how many' in q:
            return 'Objects detected: 3 items.'
        if 'compar' in q:
            return 'Yes, differences found.'
        return 'Visual analysis complete.'

    def _record(self, image_path: str, question: str) -> str:
        entry = {"image": image_path, "question": question, "turn": len(self.history) + 1}
        answer = self._mock_answer(question)
        entry["answer"] = answer
        self.history.append(entry)
        return answer

    def ask(self, image_path: str, question: str) -> str:
        return self._record(image_path, question)

    def follow_up(self, question: str) -> str:
        if not self.history:
            raise RuntimeError("No image context")
        return self._record(self.history[-1]["image"], question)

    def get_chain(self) -> list:
        return [(h["turn"], h["question"], h["answer"]) for h in self.history]


# Test it:
pipe = VisualQAPipeline("Qwen/Qwen3-VL-2B-Instruct")
a1 = pipe.ask("photo.jpg", "How many cats are in this image?")
print(a1)

a2 = pipe.follow_up("What colors are they?")
print(a2)

a3 = pipe.follow_up("Compare them to typical house cats")
print(a3)

chain = pipe.get_chain()
for turn, q, a in chain:
    print(f"Turn {turn}: {q[:20]}...")

